    /* Legacy single-group set for tests. Prefer au_affinity_pin(); this only reaches cores 0..63 in the calling thread's current group. */
    static inline bool
    au_affinity_set(int core)
    {
        AU_DWORD_PTR prev;
        if (core < 0 || core >= (int)(8 * sizeof(AU_DWORD_PTR)))
            return false;
        prev = SetThreadAffinityMask(GetCurrentThread(),
                                     ((AU_DWORD_PTR)1 << core));
        return prev != 0;
    }

    static inline void
    au_affinity_restore(const au_affinity_t* saved)
    {
        if (!saved->valid)
            return;
        (void)SetThreadGroupAffinity(GetCurrentThread(),
                                     (const struct _GROUP_AFFINITY*)&saved->prev,
                                     (struct _GROUP_AFFINITY*)0);
    }

#else /* neither Linux nor Windows: affinity unsupported -- always degrade */

    typedef struct au_affinity
    {
        bool valid;
    } au_affinity_t;

    typedef struct au_affinity_mask
    {
        bool valid;
    } au_affinity_mask_t;

    static inline bool
    au_affinity_save(au_affinity_t* saved)
    {
        saved->valid = false;
        return false;
    }
    static inline bool
    au_affinity_read_mask(au_affinity_mask_t* out)
    {
        out->valid = false;
        return false;
    }
    static inline bool
    au_affinity_set(int core)
    {
        (void)core;
        return false;
    }
    static inline bool
    au_affinity_pin(int global_core)
    {
        (void)global_core;
        return false;
    }
    static inline void
    au_affinity_restore(const au_affinity_t* saved)
    {
        (void)saved;
    }

#endif /* affinity primitives */

    /* ---- mask query helpers (operate on the flat global-index word array) --- */
#if AU_OS_IS_LINUX || AU_OS_IS_WINDOWS
    /* Is the global logical index `core` set in the allowed mask? */
    static inline bool
    au_affinity_mask_test(const au_affinity_mask_t* m, int core)
    {
        if (!m->valid || core < 0 || core >= AU_AFFINITY_MAX_CPUS)
            return false;
        return (m->w[core / (int)(8 * sizeof(unsigned long))]
                >> (core % (int)(8 * sizeof(unsigned long))))
               & 1u;
    }

    /* Lowest global logical index set in the mask, or -1 if none/invalid. C analogue of X86Cpu::getFirstCore. */
    static inline int
    au_affinity_mask_first(const au_affinity_mask_t* m)
    {
        int i, b;
        if (!m->valid)
            return -1;
        for (i = 0; i < AU_AFFINITY_NWORDS; i++) {
            if (m->w[i] == 0)
                continue;
            for (b = 0; b < (int)(8 * sizeof(unsigned long)); b++) {
                if (m->w[i] & ((unsigned long)1 << b))
                    return i * (int)(8 * sizeof(unsigned long)) + b;
            }
        }
        return -1;
    }
#else
    static inline bool
    au_affinity_mask_test(const au_affinity_mask_t* m, int core)
    {
        (void)m;
        (void)core;
        return false;
    }
    static inline int
    au_affinity_mask_first(const au_affinity_mask_t* m)
    {
        (void)m;
        return -1;
    }
#endif

    /* ---------------------------------------------------------------------- *
     *                       State: the resolved handle                       *
     * ---------------------------------------------------------------------- */

    /* Sentinel cpu number meaning "the current CPU". */
#define AU_CPUID_CURRENT_CPU (-1)

    /* Flag bitmap: dense, indexed directly by au_cpuid_flag_t. Replaces std::map<EFlag,bool>. */
#define AU_CPUID_BITMAP_WORDS (((int)AU_FLAG_MAX / 64) + 1)
    typedef struct au_flag_set
    {
        uint64_t w[AU_CPUID_BITMAP_WORDS];
    } au_flag_set_t;

    static inline void
    au_flag_set(au_flag_set_t* s, unsigned flag)
    {
        s->w[flag >> 6] |= ((uint64_t)1 << (flag & 63));
    }

    static inline bool
    au_flag_get(const au_flag_set_t* s, unsigned flag)
    {
        return (s->w[flag >> 6] >> (flag & 63)) & 1u;
    }

    /* Feature table row: run cpuid with `req`; au_cpuid_has_bits(&expected, &response) tells whether `flag` is present. */
    typedef struct au_cpuid_entry
    {
        au_cpuid_regs_t req;
        au_cpuid_regs_t expected;
        uint16_t        flag;
    } au_cpuid_entry_t;

    /* Fully-resolved CPU descriptor. au_cpuid_init() materializes it once; surfaces are pure decoders over these fields. */
    typedef struct au_cpu_info
    {
        int           cpu_num;
        au_vendor_t   vendor;
        uint16_t      family;
        uint16_t      model;
        uint16_t      stepping;
        au_uarch_t    uarch;
        au_flag_set_t avail;  /* was m_avail_flags  */
        au_flag_set_t usable; /* was m_usable_flags */
        bool          is_x86_64_v2;
        bool          is_x86_64_v3;
        bool          is_x86_64_v4;
        bool          is_zen_family;
        /* True when requested core was pinned, OR when AU_CPUID_CURRENT_CPU, OR mock/trampoline (raw_fn set). False only when specific core pin failed (graceful degrade to current core). */
        bool          affinity_honored;
        /* Mock/override hook: when non-NULL, used instead of real cpuid. Replaces virtual CpuidUtils* injection. Caller sets before au_cpuid_init(); init preserves it. */
        void (*raw_fn)(uint32_t eax,
                       uint32_t ecx,
                       au_cpuid_regs_t* out,
                       void*            ctx);
        void* raw_ctx;
    } au_cpu_info_t;

